# Try replacing 9s with the pattern values (left side pattern)
# For each 9, use the corresponding pattern value from that row

def get_pattern_value(row, col):
    """Get pattern value from left side (cols 1-3) based on row"""
    # rows 1-3: [0,5,2], rows 4-6: [0,5,2] shifted, etc.
    # Actually the pattern is: row%3 determines the sequence
    pattern_seq = [
        [0, 5, 2],  # row 1, 4, 7, 10
        [2, 4, 3],  # row 2, 5, 8, 11  
        [4, 1, 6]   # row 3, 6, 9, 12
    ]
    row_idx = (row - 1) % 3  # 0-indexed
    return pattern_seq[row_idx][col - 1]

# Build output with pattern values replacing 9s
output = []
for row in range(13):
    if row == 0 or row == 12:
        output.append([8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8])
    elif row == 4 or row == 8:
        output.append([8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8])
    elif row == 7:
        output.append([8, 4, 4, 1, 6, 4, 1, 6, 8, 4, 1])  # Use pattern [4,1,6] for cols 2-4
    else:
        new_row = grid[row][:]
        for c, val in enumerate(new_row):
            if val == 9:
                new_row[c] = get_pattern_value(row, c)
        output.append(new_row)

print(output)

